insert into T_CX_MONTH_PLAN_SURPLUS (id,month_plan_aps_version,month_plan_version, year,month,sap_code, embryo_code,month_plan_qty,plan_modify_qty,last_month_stock,sap_bad_qty, month_finish_qty,month_remain_qty,data_source,remark, del_flag,create_by,create_time, update_by,update_time) select T_CX_MONTH_PLAN_SURPLUS_SEQ.NEXTVAL AS ID, x.* from (
select #{item.monthPlanApsVersion,jdbcType=VARCHAR},#{item.monthPlanVersion,jdbcType=VARCHAR}, #{item.year,jdbcType=VARCHAR},#{item.month,jdbcType=VARCHAR},#{item.sapCode,jdbcType=VARCHAR}, #{item.embryoCode,jdbcType=VARCHAR},#{item.monthPlanQty,jdbcType=NUMERIC},#{item.planModifyQty,jdbcType=NUMERIC},#{item.lastMonthStock,jdbcType=NUMERIC},#{item.sapBadQty,jdbcType=NUMERIC}, #{item.monthFinishQty,jdbcType=NUMERIC},#{item.monthRemainQty,jdbcType=NUMERIC},#{item.dataSource,jdbcType=NUMERIC},#{item.remark,jdbcType=VARCHAR}, #{item.delFlag,jdbcType=VARCHAR},#{item.createBy,jdbcType=VARCHAR},#{item.createTime,jdbcType=TIMESTAMP}, #{item.updateBy,jdbcType=VARCHAR},#{item.updateTime,jdbcType=TIMESTAMP} from dual
) x

mapper.select:
WITH temp_table AS (

    SELECT #{item} sap_code FROM dual

)
select

from T_CX_MONTH_PLAN_SURPLUS
where
sap_code in (select sap_code from temp_table)
AND year = #{year,jdbcType=VARCHAR}
AND month = #{month,jdbcType=VARCHAR}
AND del_flag = '0'

mapper.update:
merge into T_CX_MONTH_PLAN_SURPLUS a USING (
select #{ITEM.monthPlanApsVersion,jdbcType=VARCHAR} MONTH_PLAN_APS_VERSION, #{ITEM.monthPlanVersion,jdbcType=VARCHAR} MONTH_PLAN_VERSION, #{ITEM.year,jdbcType=VARCHAR} year, #{ITEM.month,jdbcType=VARCHAR} month, #{ITEM.sapCode,jdbcType=VARCHAR} SAP_CODE, #{ITEM.monthPlanQty,jdbcType=DECIMAL} month_plan_qty, #{ITEM.planModifyQty,jdbcType=DECIMAL} plan_modify_qty, #{ITEM.lastMonthStock,jdbcType=DECIMAL} last_month_stock, #{ITEM.sapBadQty,jdbcType=DECIMAL} sap_bad_qty, #{ITEM.monthFinishQty,jdbcType=DECIMAL} month_finish_qty, #{ITEM.monthRemainQty,jdbcType=DECIMAL} month_remain_qty, #{ITEM.dataSource,jdbcType=DECIMAL} data_source, #{ITEM.createBy,jdbcType=VARCHAR} create_by, #{ITEM.createTime,jdbcType=DATE} create_time, #{ITEM.updateBy,jdbcType=VARCHAR} update_by, #{ITEM.updateTime,jdbcType=DATE} update_time, #{ITEM.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.year = b.year and b.month = a.month and b.SAP_CODE = a.SAP_CODE AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.last_month_stock = NVL(b.last_month_stock, 0), a.sap_bad_qty = NVL(b.sap_bad_qty, 0), a.month_finish_qty = NVL(b.month_finish_qty, 0), a.month_remain_qty = NVL(b.month_remain_qty, 0), a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.MONTH_PLAN_APS_VERSION, a.MONTH_PLAN_VERSION, a.year, a.month, a.sap_code, a.month_plan_qty, a.plan_modify_qty, a.last_month_stock, a.sap_bad_qty, a.month_finish_qty, a.month_remain_qty, a.data_source, a.create_by, a.create_time, a.remark, a.del_flag) values (T_CX_MONTH_PLAN_SURPLUS_SEQ.NEXTVAL, b.MONTH_PLAN_APS_VERSION, b.MONTH_PLAN_VERSION, b.year, b.month, b.sap_code, b.month_plan_qty, b.plan_modify_qty, b.last_month_stock, b.sap_bad_qty, b.month_finish_qty, b.month_remain_qty, 0, b.create_by, sysdate, b.remark, '0')
